impl RootHostControl {
 fn stage_runtime_packet_retaining(&mut self,packet:storage::Packet,expected_pid:u32,instance:&str)->Result<()> {ensure!(self.runtime_received.is_none(),"unknown original sidecar packet retained");self.runtime_received=Some(packet);let p=self.runtime_received.as_ref().unwrap();ensure!(p.credentials.pid==expected_pid as i32&&p.credentials.uid==1500&&p.credentials.gid==1500&&p.fds.is_empty()&&p.bytes.len()<=MAX_HOST_FRAME,"runtime packet is not actual original sidecar");let v:serde_json::Value=serde_json::from_slice(&p.bytes)?;
  if instance!=self.transport.sidecar_instance&&matches!(v["kind"].as_str(),Some("ready"|"host_transport_ready_v1"|"host_transport_lost_v1"|"host_transport_closed_v1"|"host_transport_activated_v1"|"host_transport_challenge_v1"|"host_transport_ack_v1")){ensure!(self.transport.historical.len()<8,"retired physical sidecar DATA retained at bound");self.transport.historical.push(self.runtime_received.take().unwrap());return Ok(());}
  match v["kind"].as_str(){
   Some("ready")=>{let ready:Ready=serde_json::from_value(v)?;ensure!(ready.version==1&&ready.nonce==self.nonce&&ready.home_id==self.data.home_id&&ready.incarnation==self.data.incarnation&&ready.config_sha256==self.digest,"replacement initial sidecar binding differs");uuid(&ready.session_generation)?;self.generation=Some(ready.session_generation);self.transport.bootstrapped=true;self.runtime_received.take();},
   Some("host_transport_ready_v1"|"host_transport_lost_v1"|"host_transport_closed_v1"|"host_transport_activated_v1")=>{let matches=self.transport.meta.as_ref().is_some_and(|m|m.matches(&v));if !matches{ensure!(self.transport.historical.len()<8,"historical transport packets retained at bound");self.transport.historical.push(self.runtime_received.take().unwrap());return Ok(());}
    match v["kind"].as_str().unwrap(){"host_transport_ready_v1"=>{ensure!(v["version"]==1&&v["home_id"]==self.data.home_id&&v["incarnation"]==self.data.incarnation&&v["config_sha256"]==self.digest,"candidate sidecar ready differs");self.transport.ready=true;},"host_transport_lost_v1"=>self.transport.offline=true,"host_transport_closed_v1"=>{self.transport.offline=true;self.transport.closed=true;},"host_transport_activated_v1"=>self.transport.activated=true,_=>unreachable!()}self.runtime_received.take();},
   Some("host_transport_challenge_v1"|"host_transport_ack_v1")=>{ensure!(self.transport.auth.len()<4,"original transport ACKs retained at bound");self.transport.auth.push_back(self.runtime_received.take().unwrap());},
   Some("engine_operation_ack_v1")=>{if self.operation_inbound.is_none(){self.operation_inbound=self.runtime_received.take();}},
   Some("engine_operation_not_forwarded_v1")=>{ensure!(self.transport.unforwarded.len()<2,"original unforwarded packets retained at bound");self.transport.unforwarded.push_back(self.runtime_received.take().unwrap());},
   _=>{let command:HostCommand=serde_json::from_value(v)?;command.validate()?;let bytes=self.runtime_received.as_ref().unwrap().bytes.clone();let pending=RootPending {command,bytes,forwarded:false,reply:None,sidecar_instance:instance.into()};
    if instance!=self.transport.sidecar_instance||self.transport.offline||Some(pending.command.session_generation.as_str())!=self.generation.as_deref(){ensure!(self.transport.orphans.len()<8,"old original host commands retained at bound");self.transport.orphans.push(pending);}else{ensure!(self.pending.is_none(),"original host command slot occupied");self.pending=Some(pending);}self.runtime_received.take();}
  }Ok(())
 }
 pub(in crate::root_storage_bootstrap) fn pump_sidecar_transport_retaining(&mut self)->Result<()> {self.check_transport_policy_current()?;
  // A full original ACK slot must not be overwritten or read past. Root's
  // operation bridge consumes it with the original MAC/nonce/budget checks.
  if self.runtime_received.is_some(){if self.operation_inbound.is_none(){let v:serde_json::Value=serde_json::from_slice(&self.runtime_received.as_ref().unwrap().bytes)?;if v["kind"]=="engine_operation_ack_v1"{self.operation_inbound=self.runtime_received.take();}}return Ok(());}if let Some(child)=&self.child{if child.status.is_none(){if let Some(packet)=self.sidecar_pair.receive()?{let pid=child.original()?.pid;let instance=self.transport.sidecar_instance.clone();self.stage_runtime_packet_retaining(packet,pid,&instance)?;}}}
  if self.runtime_received.is_some(){return Ok(());}
  let mut index=0;while index<self.transport.retired.len(){let old=&mut self.transport.retired[index];ensure!(old.child.status.is_some()&&old.child.original()?.exited()?,"retired sidecar not actually reaped/exited");old.peer.take();
   let mut byte=0u8;let n=unsafe{libc::recv(old.poll.as_raw_fd(),(&mut byte as *mut u8).cast(),1,libc::MSG_PEEK|libc::MSG_DONTWAIT)};
   if n==0{self.transport.retired.remove(index);continue;}if n<0{ensure!(std::io::Error::last_os_error().kind()==std::io::ErrorKind::WouldBlock,"retired original endpoint read uncertain");index+=1;continue;}
   let pid=old.child.original()?.pid;let instance=old.instance.clone();let packet=old.endpoint.receive()?;if let Some(packet)=packet{self.stage_runtime_packet_retaining(packet,pid,&instance)?;if self.runtime_received.is_some(){break;}}index+=1;
  }Ok(())
 }
 fn pump_native_transport_retaining(&mut self,engine:&Process)->Result<()> {engine.live()?;if self.transport.native_received.is_none(){self.transport.native_received=self.native_pair.receive()?;}let Some(packet)=&self.transport.native_received else{return Ok(());};ensure!(packet.credentials.pid==engine.pid as i32&&packet.credentials.uid==1500&&packet.credentials.gid==1500&&packet.fds.is_empty()&&packet.bytes.len()<=MAX_HOST_FRAME,"native runtime packet differs from original engine");let v:serde_json::Value=serde_json::from_slice(&packet.bytes)?;
  if v["kind"]=="host_transport_native_accepted_v1"{if !self.transport.meta.as_ref().is_some_and(|m|m.matches(&v)){ensure!(self.transport.historical.len()<8,"stale native generation ACKs retained at bound");self.transport.historical.push(self.transport.native_received.take().unwrap());return Ok(());}ensure!(self.transport.native_ack.is_none(),"original native generation ACK already retained");self.transport.native_ack=self.transport.native_received.take();return Ok(());}
  let reply:HostReply=serde_json::from_value(v)?;let matches=|p:&RootPending|reply.session_generation==p.command.session_generation&&reply.rpc_id==p.command.rpc_id&&reply.command_key==p.command.command_key;
  if self.pending.as_ref().is_some_and(&matches){let pending=self.pending.as_mut().unwrap();ensure!(pending.reply.is_none(),"duplicate original native reply");reply.validate_for(&pending.command)?;pending.reply=self.transport.native_received.take();return Ok(());}
  let old=self.transport.orphans.iter_mut().find(|p|matches(p)).context("native reply has no original retained command")?;ensure!(old.forwarded&&old.reply.is_none(),"late original reply differs");reply.validate_for(&old.command)?;old.reply=self.transport.native_received.take();Ok(())
 }
 pub(in crate::root_storage_bootstrap) fn check_actual_sidecar_for_generation(&self)->Result<()> {self.current()?;ensure!(self.transport.ready&&!self.transport.closed,"actual candidate sidecar generation absent");let process=self.child.as_ref().context("actual candidate sidecar Child absent")?.original()?;self.node.matches_process(process)?;self.node.matches_fd(self.exe.as_ref().context("actual candidate proc-exe absent")?)?;ensure!(self.namespaces.len()==4,"actual candidate namespaces absent");Ok(())}
 pub(in crate::root_storage_bootstrap) fn poll_transport_health_retaining(&mut self,engine:&Process)->Result<bool>{self.check_transport_policy_current()?;engine.live()?;
  if let Some(child)=&mut self.child {if child.status.is_none(){child.status=child.child.try_wait()?;}if child.status.is_some(){ensure!(child.original()?.exited()?,"original sidecar wait/pidfd disagreement");self.transport.offline=true;self.transport.closed=true;}}
  self.pump_sidecar_transport_retaining()?;self.pump_native_transport_retaining(engine)?;self.flush_offline_notice_retaining()?;Ok(self.transport.offline)
 }
 fn retire_dead_sidecar_retaining(&mut self)->Result<()> {let Some(child)=&self.child else{return Ok(());};if child.status.is_none(){return Ok(());}ensure!(child.original()?.exited()?,"old sidecar not physically exited");ensure!(self.transport.retired.len()<4,"unsettled original sidecar carriers retained at bound");
  let (root,peer)=storage::bootstrap_socket_pair()?;let poll=root.try_clone()?;let endpoint=Endpoint::capture(root)?;
  let old=RetiredSidecar {instance:self.transport.sidecar_instance.clone(),child:self.child.take().unwrap(),endpoint:std::mem::replace(&mut self.sidecar_pair,endpoint),poll:std::mem::replace(&mut self.transport.poll,poll),peer:Some(std::mem::replace(&mut self.child_endpoint,peer)),exe:self.exe.take(),namespaces:std::mem::take(&mut self.namespaces)};
  self.transport.retired.push(old);self.transport.sidecar_instance=uuid::Uuid::new_v4().to_string();self.attempted=false;self.generation=None;self.ready_packet.take();self.transport.bootstrapped=false;Ok(())
 }
 fn spawn_replacement_sidecar_retaining(&mut self,budget:&FinalizationBudget)->Result<bool>{self.check_transport_policy_current()?;budget.remaining()?;if self.child.is_some(){return Ok(true);}ensure!(!self.attempted,"actual sidecar capture/spawn outcome retained");
  let config:OwnedFd=self.file.try_clone()?.into();let token:OwnedFd=self.token.try_clone()?.into();let uptime:OwnedFd=self.uptime.try_clone()?.into();
  let data=super::super::sealed_bytes(&canonical_json(&serde_json::json!({"version":1,"nonce":self.nonce,"constraint":budget.constraint()}))?)?;
  let (mut command,held)=super::super::mapped_command(NODE,&["--no-addons","--disable-proto=throw",SIDECAR],false,&[(&self.child_endpoint,3),(&config,4),(&token,5),(&uptime,6),(&data,7)])?;
  unsafe {command.pre_exec(||{if libc::setgroups(0,std::ptr::null())!=0{return Err(std::io::Error::last_os_error());}for cap in 0..=63 {if libc::prctl(libc::PR_CAPBSET_READ,cap,0,0,0)==1&&libc::prctl(libc::PR_CAPBSET_DROP,cap,0,0,0)!=0{return Err(std::io::Error::last_os_error());}}
   if libc::prctl(libc::PR_SET_NO_NEW_PRIVS,1,0,0,0)!=0||libc::prctl(libc::PR_SET_KEEPCAPS,0,0,0,0)!=0||libc::prctl(libc::PR_CAP_AMBIENT,libc::PR_CAP_AMBIENT_CLEAR_ALL,0,0,0)!=0||libc::setresgid(1500,1500,1500)!=0||libc::setresuid(1500,1500,1500)!=0{return Err(std::io::Error::last_os_error());}super::super::clear_capabilities()?;Ok(())});}
  budget.remaining()?;match super::super::spawn_retaining(&mut self.child,&mut command)? {super::super::SpawnEffect::DefiniteError=>return Ok(false),super::super::SpawnEffect::ChildStored=>self.attempted=true}drop(held);
  let process=self.child.as_ref().unwrap().original()?;self.exe=Some(File::open(format!("/proc/{}/exe",process.pid))?.into());self.node.matches_fd(self.exe.as_ref().unwrap())?;
  for(name,kind)in[("mnt",libc::CLONE_NEWNS),("user",libc::CLONE_NEWUSER),("net",libc::CLONE_NEWNET),("pid",libc::CLONE_NEWPID)]{self.namespaces.push((name.into(),storage::namespace(Some(process.pid),name,kind)?,kind));}
  budget.remaining()?;self.current()?;Ok(true)
 }
 pub(in crate::root_storage_bootstrap) fn connect_transport_generation_retaining(&mut self,serial:&str,generation:&str,nonce:&str,budget:&FinalizationBudget)->Result<bool>{self.check_transport_policy_current()?;budget.remaining()?;
  if self.transport.meta.as_ref().is_none_or(|m|m.attempt_nonce!=nonce){if !self.transport.closed&&self.transport.meta.is_some(){return Ok(false);}if let Some(old)=self.transport.offer.take(){if !self.transport.activated{ensure!(self.transport.old_offers.len()<8,"unknown generation offers retained at bound");self.transport.old_offers.push(old);}}
   self.transport.meta=Some(Meta {serial:serial.into(),generation:generation.into(),attempt_nonce:nonce.into()});self.transport.ready=false;self.transport.activated=false;self.transport.connect_sent=false;self.transport.connect_wire=None;self.transport.active_sent=false;self.transport.close_sent=false;self.transport.closed=false;}
  self.retire_dead_sidecar_retaining()?;if !self.spawn_replacement_sidecar_retaining(budget)?{return Ok(false);}if !self.transport.bootstrapped&&self.generation.is_none(){self.pump_sidecar_transport_retaining()?;if !self.transport.bootstrapped{return Ok(false);}}
  if self.transport.connect_sent{return Ok(true);}let wire=canonical_json(&serde_json::json!({"kind":"host_transport_connect_v1","serial":serial,"generation":generation,"attempt_nonce":nonce,"constraint":budget.constraint()}))?;
  if let Some(old)=&self.transport.connect_wire{ensure!(*old==wire,"original Root connect packet changed");}else{self.transport.connect_wire=Some(wire);}
  self.current()?;budget.remaining()?;if !self.sidecar_pair.send(self.transport.connect_wire.as_ref().unwrap(),None)?{return Ok(false);}self.transport.connect_sent=true;budget.remaining()?;Ok(true)
 }
 pub(in crate::root_storage_bootstrap) fn transport_generation_ready(&self,serial:&str,generation:&str,nonce:&str)->Result<bool>{self.check_transport_policy_current()?;let m=self.transport.meta.as_ref().context("original generation attempt absent")?;ensure!(m.serial==serial&&m.generation==generation&&m.attempt_nonce==nonce,"candidate generation differs");Ok(self.transport.ready&&!self.transport.closed)}
 pub(in crate::root_storage_bootstrap) fn transport_send_retaining(&mut self,bytes:&[u8])->Result<bool>{self.check_actual_sidecar_for_generation()?;ensure!(bytes.len()<=MAX_HOST_FRAME,"transport auth packet exceeds bound");self.sidecar_pair.send(bytes,None)}
 pub(in crate::root_storage_bootstrap) fn transport_receive_retaining(&mut self,out:&mut Option<storage::Packet>)->Result<()> {ensure!(out.is_none(),"original transport auth packet already retained");self.pump_sidecar_transport_retaining()?;*out=self.transport.auth.pop_front();Ok(())}
 pub(in crate::root_storage_bootstrap) fn original_proxy_target(&self)->Result<Option<serde_json::Value>>{self.check_transport_policy_current()?;if self.transport.offline{return Ok(None);}self.check_actual_sidecar_for_generation()?;let m=self.transport.meta.as_ref().context("actual proxy generation absent")?;Ok(Some(serde_json::json!({"serial":m.serial,"generation":m.generation,"attempt_nonce":m.attempt_nonce})))}
 pub(in crate::root_storage_bootstrap) fn take_unforwarded_retaining(&mut self,out:&mut Option<storage::Packet>)->Result<()> {ensure!(out.is_none(),"original no-forward packet output occupied");self.pump_sidecar_transport_retaining()?;*out=self.transport.unforwarded.pop_front();Ok(())}
 pub(in crate::root_storage_bootstrap) fn offer_native_generation_retaining(&mut self,serial:&str,generation:&str,nonce:&str,budget:&FinalizationBudget)->Result<bool>{self.check_actual_sidecar_for_generation()?;budget.remaining()?;if !self.flush_offline_notice_retaining()?{return Ok(false);}
  if self.transport.offer.is_none(){let process=self.child.as_ref().unwrap().original()?;self.transport.offer=Some(Offer {meta:Meta {serial:serial.into(),generation:generation.into(),attempt_nonce:nonce.into()},constraint:budget.constraint(),fds:Vec::new(),index:0,unknown:false});
   let offer=self.transport.offer.as_mut().unwrap();offer.fds.push(process.fd().try_clone()?);offer.fds.push(self.exe.as_ref().context("actual sidecar image absent")?.try_clone()?);for(_,file,_)in&self.namespaces{offer.fds.push(file.try_clone()?.into());}}
  let o=self.transport.offer.as_mut().unwrap();ensure!(!o.unknown&&o.meta.serial==serial&&o.meta.generation==generation&&o.meta.attempt_nonce==nonce&&o.constraint==budget.constraint()&&o.fds.len()==6,"original generation offer differs/uncertain");if o.index==6{return Ok(true);}
  let labels=["sidecar","exe","mnt","user","net","pid"];let frame=transport_native::NativeOffer {version:1,kind:"host_transport_offer_v1".into(),serial:serial.into(),generation:generation.into(),attempt_nonce:nonce.into(),config_sha256:self.digest.clone(),root_nonce:self.nonce.clone(),constraint:o.constraint.clone(),label:labels[o.index].into()};
  match self.native_pair.send(&canonical_json(&frame)?,Some(&o.fds[o.index])){Ok(true)=>{o.index+=1;budget.remaining()?;Ok(o.index==6)},Ok(false)=>Ok(false),Err(error)=>{o.unknown=true;Err(error)}}
 }
 pub(in crate::root_storage_bootstrap) fn native_generation_ack_retaining(&mut self,out:&mut Option<storage::Packet>,engine:&Process)->Result<()> {ensure!(out.is_none(),"native generation ACK output occupied");self.pump_native_transport_retaining(engine)?;*out=self.transport.native_ack.take();Ok(())}
 pub(in crate::root_storage_bootstrap) fn activate_native_generation_retaining(&mut self,serial:&str,generation:&str,nonce:&str,budget:&FinalizationBudget)->Result<bool>{self.check_actual_sidecar_for_generation()?;budget.remaining()?;let frame=transport_native::NativeState {version:1,kind:"host_transport_active_v1".into(),serial:serial.into(),generation:generation.into(),attempt_nonce:nonce.into(),config_sha256:self.digest.clone()};let sent=self.native_pair.send(&canonical_json(&frame)?,None)?;budget.remaining()?;Ok(sent)}
 pub(in crate::root_storage_bootstrap) fn activate_sidecar_generation_retaining(&mut self,serial:&str,generation:&str,nonce:&str,budget:&FinalizationBudget)->Result<bool>{self.check_actual_sidecar_for_generation()?;budget.remaining()?;
  if !self.transport.active_sent{let frame=serde_json::json!({"kind":"host_transport_activate_v1","serial":serial,"generation":generation,"attempt_nonce":nonce,"constraint":budget.constraint()});if !self.sidecar_pair.send(&canonical_json(&frame)?,None)?{return Ok(false);}self.transport.active_sent=true;}
  self.pump_sidecar_transport_retaining()?;if !self.transport.activated{return Ok(false);}self.transport.offline=false;self.generation=Some(generation.into());budget.remaining()?;Ok(true)
 }
 fn flush_offline_notice_retaining(&mut self)->Result<bool>{ensure!(!self.transport.offline_unknown,"original offline notice send uncertain");let Some(bytes)=&self.transport.offline_wire else{return Ok(true);};match self.native_pair.send(bytes,None){Ok(true)=>{self.transport.offline_wire.take();Ok(true)},Ok(false)=>Ok(false),Err(error)=>{self.transport.offline_unknown=true;Err(error)}}}
 pub(in crate::root_storage_bootstrap) fn pause_native_transport_retaining(&mut self)->Result<()> {self.transport.offline=true;if self.transport.offline_wire.is_none(){if let Some(m)=&self.transport.meta{let frame=transport_native::NativeState {version:1,kind:"host_transport_offline_v1".into(),serial:m.serial.clone(),generation:m.generation.clone(),attempt_nonce:m.attempt_nonce.clone(),config_sha256:self.digest.clone()};self.transport.offline_wire=Some(canonical_json(&frame)?);}}self.flush_offline_notice_retaining()?;Ok(())}
 pub(in crate::root_storage_bootstrap) fn close_unknown_transport_retaining(&mut self,_serial:&str,_generation:&str,_nonce:&str)->Result<bool>{self.check_transport_policy_current()?;if self.transport.closed{return Ok(true);}if let Some(child)=&mut self.child{if child.status.is_none(){child.status=child.child.try_wait()?;}if child.status.is_some(){ensure!(child.original()?.exited()?,"actual sidecar exit disagreement");self.transport.closed=true;return Ok(true);}}
  if !self.transport.close_sent{let Some(actual)=&self.transport.meta else{return Ok(false);};let frame=serde_json::json!({"kind":"host_transport_close_v1","serial":actual.serial,"generation":actual.generation,"attempt_nonce":actual.attempt_nonce});if !self.sidecar_pair.send(&canonical_json(&frame)?,None)?{return Ok(false);}self.transport.close_sent=true;}self.pump_sidecar_transport_retaining()?;Ok(self.transport.closed)
 }
 pub(in crate::root_storage_bootstrap) fn deliver_late_reply_data_retaining(&mut self)->Result<()> {let mut index=0;while index<self.transport.orphans.len(){let old=&self.transport.orphans[index];let Some(reply)=&old.reply else{index+=1;continue;};
   // Reply DATA is an actual original Native receipt. It says nothing about
   // backend completion, helper/actor drain, or delivery on the old Cloud WS.
   if old.sidecar_instance==self.transport.sidecar_instance&&self.child.as_ref().is_some_and(|c|c.status.is_none()){self.current()?;if !self.sidecar_pair.send(&reply.bytes,None)?{index+=1;continue;}}
   let known=self.transport.orphans.remove(index);self.transport.known_receipts.push_back(known);if self.transport.known_receipts.len()>64{self.transport.known_receipts.pop_front();}
  }Ok(())}
}
